SourceCode.Declaration:
/// <summary>
/// CB223_PalletRounding
/// Pallet rounding logic for a sales order line.
/// </summary>
internal final class METSalesLinePalletRoundingProcess
{
    SalesId         salesId;
    ItemId          itemId;
    CustAccount     custAccount;
    SalesUnit       salesUnit;
    SalesQty        salesQtySum;
    InventSiteId    inventSiteId;
    InventDimId     inventDimId;

    METInventItemOrderSetup metInventItemOrderSetup;

}

Method.Source:
/// <summary>
/// Construct
/// </summary>
/// <param name = "_salesId">Sales order id</param>
/// <param name = "_itemId">Item number</param>
/// <param name = "_custAccount">Customer account</param>
/// <param name = "_salesUnit">Sales order line UOM</param>
/// <param name = "_salesQtySum">Sum of qty for the same item in the SO</param>
/// <param name = "_inventDimId">Inventory dimension id</param>
/// <param name = "_inventSiteId">Site</param>
/// <returns>New instance of <c>METSalesLinePalletRoundingProcess</c> class</returns>
static METSalesLinePalletRoundingProcess construct(SalesId      _salesId,
                                                   ItemId       _itemId,
                                                   CustAccount  _custAccount,
                                                   SalesUnit    _salesUnit,
                                                   SalesQty     _salesQtySum,
                                                   InventDimId  _inventDimId,
                                                   InventSiteId _inventSiteId)
{
    if (!_salesId || !_itemId || !_custAccount || !_salesUnit || !_salesQtySum || !_inventDimId || !_inventSiteId)
    {
        throw error(strFmt("@SYS19306", funcName()));
    }

    return new METSalesLinePalletRoundingProcess(_salesId, _itemId, _custAccount, _salesUnit, _salesQtySum, _inventDimId, _inventSiteId);
}

/// <summary>
/// New method
/// </summary>
/// <param name = "_salesId">Sales order id</param>
/// <param name = "_itemId">Item number</param>
/// <param name = "_custAccount">Customer account</param>
/// <param name = "_salesUnit">Sales order line UOM</param>
/// <param name = "_salesQtySum">Sum of qty for the same item in the SO</param>
/// <param name = "_inventDimId">Inventory dimension id</param>
/// <param name = "_inventSiteId">Site</param>
protected void new(SalesId      _salesId,
                   ItemId       _itemId,
                   CustAccount  _custAccount,
                   SalesUnit    _salesUnit,
                   SalesQty     _salesQtySum,
                   InventDimId  _inventDimId,
                   InventSiteId _inventSiteId)
{
    salesId         = _salesId;
    itemId          = _itemId;
    custAccount     = _custAccount;
    salesUnit       = _salesUnit;
    salesQtySum     = _salesQtySum;
    inventDimId     = _inventDimId;
    inventSiteId    = _inventSiteId;
}

/// <summary>
/// Run the sales order line pallet rounding
/// </summary>
/// <returns>True if the line was processed, even if no pallet rounding policy; otherwise, returns false if validation failed.</returns>
boolean run()
{
    boolean processed = true;

    // Check 1: The sales order line site, item and customer match an active pallet rounding policy.
    METPalletRoundingPolicySearch search = METPalletRoundingPolicySearch::construct(custAccount, inventSiteId, itemId, salesUnit, salesQtySum, inventDimId);
    METPalletRoundingPolicySearchResultantHelper metPalletRoundingPolicySearchResultantHelper = search.search();

    METPalletRoundingPolicyLine palletRoundingPolicyLine = metPalletRoundingPolicySearchResultantHelper.parmMETPalletRoundingPolicyLine();

    if (palletRoundingPolicyLine)
    {
        if (metPalletRoundingPolicySearchResultantHelper.parmHasInventOrderSetup())
        {
            this.palletRoundUp(metPalletRoundingPolicySearchResultantHelper);
        }
        else
        {
            processed = false;
        }
    }

    return processed;
}

/// <summary>
/// Roundup sales order line qty to pallet
/// </summary>
/// <param name = "_metPalletRoundingPolicySearchResultantHelper">METPalletRoundingPolicySearchResultantHelper class object having Pallet rounding policy line and other details</param>
void palletRoundUp(METPalletRoundingPolicySearchResultantHelper _metPalletRoundingPolicySearchResultantHelper)
{        
    METPalletRoundingPolicyLine palletRoundingPolicyLine = _metPalletRoundingPolicySearchResultantHelper.parmMETPalletRoundingPolicyLine();
    SalesQty salesLineRoundedSalesQty = _metPalletRoundingPolicySearchResultantHelper.parmSalesLineRoundedSalesQty();

    ttsbegin;
    // find the original sales line (not the bonus stock one)
    SalesLine salesLine = SalesLine::metFindBonusStock(salesId, itemId, custAccount, salesUnit, inventDimId, NoYes::No, true);

    if (salesLine)
    {
        SalesQty origSalesQty = salesLine.SalesQty;

        // round up to pallet qty
        salesLine.SalesQty += salesLineRoundedSalesQty;

        // very important to call this to update inventTrans qty and remainder qty
        salesLine.salesQtyModified();
        salesLine.update();

        METSalesLine metSalesLine = METSalesLine::find(salesLine.RecId, true);

        if (metSalesLine)
        {
            metSalesLine.PalletRoundingApplied              = NoYes::Yes;
            metSalesLine.PalletRoundingOriginalQty          = origSalesQty;
            metSalesLine.PalletRoundingPolicyLineRefRecId   = palletRoundingPolicyLine.RecId;
            metSalesLine.PalletRoundingPercentage           = palletRoundingPolicyLine.RoundingPercentage;
            metSalesLine.RoundingPolicyType                 = palletRoundingPolicyLine.PolicyType;

            metSalesLine.update();
        }
        else
        {
            throw error(strFmt("@MET:PalletRoundingMETSalesLineError", salesId,
                                                                        itemId, 
                                                                        custAccount, 
                                                                        salesUnit, 
                                                                        inventDimId));
        }
    }
    else
    {
        throw error(strFmt("@MET:PalletRoundingSalesLineError", salesLine.RecId));
    }
    ttscommit;

}

/// <summary>
/// Validate before rounding policy is applied.
/// </summary>
/// <param name = "_palletRoundingPolicyLine">METPalletRoundingPolicyLine buffer</param>
/// <returns>True if validation successful; otherwise, false</returns>
protected boolean validate(METPalletRoundingPolicyLine _palletRoundingPolicyLine)
{
    boolean ret = true;
    // retrieve default order settings
    metInventItemOrderSetup = METInventItemOrderSetup::findByItemAndSite(itemId, inventSiteId);

    if (!metInventItemOrderSetup)
    {
        ret = checkFailed(strFmt("@MET:PalletRoundingInventItemOrderSetupError", itemId, inventSiteId));
    }

    if (ret)
    {
        if (_palletRoundingPolicyLine.PolicyType == METRoundingPolicyType::Pallet)
        {
            if (!metInventItemOrderSetup.PalletQty)
            {
                ret = checkFailed(strFmt("@MET:PalletRoundingInventItemOrderSetupPalletQtyError", fieldPName(METInventItemOrderSetup, PalletQty), itemId, inventSiteId));
            }

            if (!metInventItemOrderSetup.CartonPerPallet)
            {
                ret = checkFailed(strFmt("@MET:PalletRoundingInventItemOrderSetupPalletQtyError", fieldPName(METInventItemOrderSetup, CartonPerPallet), itemId, inventSiteId));
            }
        }
        else if (_palletRoundingPolicyLine.PolicyType == METRoundingPolicyType::Layer)
        {
            if (!metInventItemOrderSetup.PalletLayerQty)
            {
                ret = checkFailed(strFmt("@MET:PalletRoundingInventItemOrderSetupPalletQtyError", fieldPName(METInventItemOrderSetup, PalletLayerQty), itemId, inventSiteId));
            }

            if (!metInventItemOrderSetup.CartonPerLayer)
            {
                ret = checkFailed(strFmt("@MET:PalletRoundingInventItemOrderSetupPalletQtyError", fieldPName(METInventItemOrderSetup, CartonPerLayer), itemId, inventSiteId));
            }
        }
    }

    return ret;
}
